using Rhino;using Rhino.PlugIns;using Rhino.UI;
namespace RhinoContextAssist;
public sealed class ContextAssistPlugIn:PlugIn{internal static ContextAssistPlugIn? Instance{get;private set;}internal ContextAssistController? Controller{get;private set;}internal ContextAssistSettings SettingsModel{get;private set;}=null!;internal ContextAction? LastAction{get;set;}public ContextAssistPlugIn()=>Instance=this;protected override LoadReturnCode OnLoad(ref string e){SettingsModel=new(Settings);Controller=new(SettingsModel);Controller.Start();RhinoApp.WriteLine("Rhino Context Assist 1.4 geladen.");return LoadReturnCode.Success;}protected override void OptionsDialogPages(List<OptionsDialogPage> p)=>p.Add(new ContextAssistOptionsPage(SettingsModel));protected override void OnShutdown(){Controller?.Dispose();}}
